import{_ as l}from"./BEfvH6V6.js";import{q as o,Q as n,k as x,h as t,o as a,ag as r,n as d,m as i}from"./CUD-SFDH.js";const c={class:"space-y-6 transition-colors duration-200"},b={class:"flex items-center justify-between"},p={class:"text-center"},f=o({__name:"ai-training-guide",setup(m){return(g,e)=>{const s=l;return n(),x("div",c,[t("div",b,[a(s,{to:"/dashboard/pages",class:"inline-flex items-center gap-1.5 text-sm text-slate-600 hover:text-slate-900 dark:text-slate-400 dark:hover:text-slate-200 transition-colors"},{default:r(()=>[...e[0]||(e[0]=[t("span",{class:"material-icons select-none text-base"},"arrow_back",-1),d(" ກັບຄືນຫາໜ້າເພຈ໌ ",-1)])]),_:1})]),e[2]||(e[2]=i('<div class="bg-white dark:bg-slate-900/40 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm dark:shadow-lg transition-colors"><div class="flex items-start gap-4"><div class="w-12 h-12 rounded-2xl bg-indigo-100 dark:bg-indigo-500/15 flex items-center justify-center shrink-0"><span class="material-icons select-none text-2xl text-indigo-600 dark:text-indigo-400">auto_awesome</span></div><div><h1 class="text-2xl font-extrabold text-slate-900 dark:text-slate-100"> ຄູ່ມືການຝຶກສອນ AI </h1><p class="text-sm text-slate-500 dark:text-slate-400 mt-1 leading-relaxed"> ຮຽນຮູ້ວ່າຂໍ້ມູນແບບໃດຄວນ ແລະ ບໍ່ຄວນໃສ່ໃນຖານຂໍ້ມູນຄວາມຮູ້ (Knowledge Base) ເພື່ອໃຫ້ AI ຕອບແຊັດລູກຄ້າໄດ້ຢ່າງຖືກຕ້ອງ ແລະ ມີປະສິດທິພາບ. </p></div></div></div><div class="bg-white dark:bg-slate-900/40 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm dark:shadow-lg transition-colors"><h2 class="font-bold text-lg text-slate-900 dark:text-slate-200 flex items-center gap-2 mb-4"><span class="material-icons select-none text-indigo-600 dark:text-indigo-400">psychology</span> ວິທີທີ່ AI ໃຊ້ຖານຂໍ້ມູນຄວາມຮູ້ (Knowledge Base) </h2><div class="space-y-3 text-sm text-slate-600 dark:text-slate-400 leading-relaxed"><div class="flex items-start gap-3 p-3 bg-slate-50 dark:bg-slate-950/30 rounded-xl border border-slate-200 dark:border-slate-800/40"><span class="material-icons select-none text-lg text-indigo-600 dark:text-indigo-400 shrink-0 mt-0.5">looks_one</span><div><p class="font-semibold text-slate-800 dark:text-slate-200">ທ່ານຂຽນຂໍ້ມູນຮ້ານຄ້າ ລົງໃນກ່ອງຂໍ້ຄວາມ KB</p><p class="text-xs text-slate-500 mt-0.5">ເຊັ່ນ: ເວລາເປີດ-ປິດ, ລາຄາສິນຄ້າ, ນະໂຍບາຍຕ່າງໆ, FAQ</p></div></div><div class="flex items-start gap-3 p-3 bg-slate-50 dark:bg-slate-950/30 rounded-xl border border-slate-200 dark:border-slate-800/40"><span class="material-icons select-none text-lg text-indigo-600 dark:text-indigo-400 shrink-0 mt-0.5">looks_two</span><div><p class="font-semibold text-slate-800 dark:text-slate-200">AI ອ່ານຂໍ້ມູນ KB ພ້ອມກັບປະຫວັດແຊັດ ແລະ ໂປຣໄຟລ໌ລູກຄ້າ</p><p class="text-xs text-slate-500 mt-0.5">AI ຈະເອົາຂໍ້ມູນທັງໝົດມາວິເຄາະກ່ອນຕອບ</p></div></div><div class="flex items-start gap-3 p-3 bg-slate-50 dark:bg-slate-950/30 rounded-xl border border-slate-200 dark:border-slate-800/40"><span class="material-icons select-none text-lg text-indigo-600 dark:text-indigo-400 shrink-0 mt-0.5">looks_3</span><div><p class="font-semibold text-slate-800 dark:text-slate-200">AI ສ້າງຄຳຕອບໂດຍອີງຕາມ KB ເທົ່ານັ້ນ</p><p class="text-xs text-slate-500 mt-0.5">ຖ້າບໍ່ມີຂໍ້ມູນໃນ KB, AI ຈະບອກວ່າບໍ່ຮູ້ ແລະ ໃຫ້ພະນັກງານຕິດຕໍ່ກັບໄປ — <strong class="text-rose-600 dark:text-rose-400">ມັນຈະບໍ່ເຄີຍສ້າງຂໍ້ມູນຂຶ້ນເອງ</strong></p></div></div><div class="flex items-start gap-3 p-3 bg-slate-50 dark:bg-slate-950/30 rounded-xl border border-slate-200 dark:border-slate-800/40"><span class="material-icons select-none text-lg text-indigo-600 dark:text-indigo-400 shrink-0 mt-0.5">looks_4</span><div><p class="font-semibold text-slate-800 dark:text-slate-200">ສົ່ງຂໍ້ຄວາມຕອບກັບໄປຫາລູກຄ້າຜ່ານ Facebook Messenger</p><p class="text-xs text-slate-500 mt-0.5">ໂດຍອັດຕະໂນມັດ ຜ່ານ Webhook ທີ່ເຊື່ອມຕໍ່ກັບ Facebook</p></div></div></div></div><div class="bg-white dark:bg-slate-900/40 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm dark:shadow-lg transition-colors"><div class="flex items-center gap-3 mb-5"><div class="w-10 h-10 rounded-xl bg-emerald-100 dark:bg-emerald-500/15 flex items-center justify-center"><span class="material-icons select-none text-xl text-emerald-600 dark:text-emerald-400">check_circle</span></div><div><h2 class="font-bold text-lg text-slate-900 dark:text-slate-100">ຂໍ້ມູນທີ່ຄວນໃສ່ ✅</h2><p class="text-xs text-slate-500 dark:text-slate-400">ຂໍ້ມູນທີ່ຈຳເປັນ ແລະ ຖືກຕ້ອງ ເພື່ອໃຫ້ AI ສາມາດຕອບໄດ້ຖືກຕ້ອງ</p></div></div><div class="space-y-5"><div class="border border-emerald-200 dark:border-emerald-500/20 rounded-xl overflow-hidden"><div class="bg-emerald-50 dark:bg-emerald-500/5 px-4 py-3 border-b border-emerald-200 dark:border-emerald-500/20"><h3 class="font-bold text-sm text-emerald-800 dark:text-emerald-300 flex items-center gap-2"><span class="material-icons select-none text-base">store</span> 1. ຂໍ້ມູນຮ້ານຄ້າ (ບັງຄັບ) </h3></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ຂໍ້ມູນພື້ນຖານທີ່ AI ຕ້ອງການເພື່ອແນະນຳຮ້ານຄ້າໃຫ້ລູກຄ້າ:</p><div class="bg-slate-50 dark:bg-slate-950/40 rounded-lg p-3 font-mono text-xs text-slate-700 dark:text-slate-300 leading-relaxed border border-slate-200 dark:border-slate-800/50"> ຊື່ຮ້ານ: ສະບາຍດີຊົອບ<br> ທີ່ຢູ່: ບ້ານສີຫອມ, ເມືອງຈັນທະບູລີ, ນະຄອນຫຼວງວຽງຈັນ<br> ເບີໂທຕິດຕໍ່: 020 12345678<br> ເວັບໄຊ: www.sabaideeshop.la<br> ອີເມວ: info@sabaideeshop.la </div><p class="text-xs text-emerald-600 dark:text-emerald-500 font-semibold">✅ AI ຈະສາມາດບອກລູກຄ້າໄດ້ວ່າຮ້ານຢູ່ໃສ, ຕິດຕໍ່ແນວໃດ</p></div></div><div class="border border-emerald-200 dark:border-emerald-500/20 rounded-xl overflow-hidden"><div class="bg-emerald-50 dark:bg-emerald-500/5 px-4 py-3 border-b border-emerald-200 dark:border-emerald-500/20"><h3 class="font-bold text-sm text-emerald-800 dark:text-emerald-300 flex items-center gap-2"><span class="material-icons select-none text-base">schedule</span> 2. ເວລາເປີດ-ປິດ (ບັງຄັບ) </h3></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ລະບຸເວລາເປີດ-ປິດຂອງຮ້ານໃຫ້ຊັດເຈນ ເປັນຮູບແບບປະຈຳ:</p><div class="bg-slate-50 dark:bg-slate-950/40 rounded-lg p-3 font-mono text-xs text-slate-700 dark:text-slate-300 leading-relaxed border border-slate-200 dark:border-slate-800/50"> ວັນຈັນ ຫາ ວັນສຸກ: 8:00 - 17:00 ໂມງ<br> ວັນເສົາ: 9:00 - 12:00 ໂມງ<br> ວັນອາທິດ ແລະ ວັນພັກລັດຖະການ: ປິດ </div><p class="text-xs text-emerald-600 dark:text-emerald-500 font-semibold">✅ AI ຈະຕອບຄຳຖາມ &quot;ເປີດຮ້ານວັນໃດແດ່?&quot; ໄດ້ຖືກຕ້ອງ</p></div></div><div class="border border-emerald-200 dark:border-emerald-500/20 rounded-xl overflow-hidden"><div class="bg-emerald-50 dark:bg-emerald-500/5 px-4 py-3 border-b border-emerald-200 dark:border-emerald-500/20"><h3 class="font-bold text-sm text-emerald-800 dark:text-emerald-300 flex items-center gap-2"><span class="material-icons select-none text-base">inventory_2</span> 3. ລາຍການສິນຄ້າ ແລະ ລາຄາ (ບັງຄັບ) </h3></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ລະບຸຊື່ສິນຄ້າ, ຂະໜາດ/ນ້ຳໜັກ, ແລະ ລາຄາໃຫ້ຊັດເຈນ:</p><div class="bg-slate-50 dark:bg-slate-950/40 rounded-lg p-3 font-mono text-xs text-slate-700 dark:text-slate-300 leading-relaxed border border-slate-200 dark:border-slate-800/50"> 1. ແຢມສະຕໍເບີຣີປອດສານພິດ (250g) — 45,000 ກີບ/ກະປຸກ<br> 2. ເຂົ້າຈີ່ຝຣັ່ງເສັ້ນໃຫຍ່ (200g) — 20,000 ກີບ/ອັນ<br> 3. ນ້ຳເຜິ້ງດອກໄມ້ປ່າ 100% (500ml) — 80,000 ກີບ/ຂວດ<br> 4. ຊາໃບໝາກນາວຫອມ (50g) — 25,000 ກີບ/ຖົງ </div><p class="text-xs text-emerald-600 dark:text-emerald-500 font-semibold">✅ AI ຈະຕອບຄຳຖາມ &quot;ມີຫຍັງຂາຍແດ່? ລາຄາເທົ່າໃດ?&quot; ໄດ້ຖືກຕ້ອງ</p></div></div><div class="border border-emerald-200 dark:border-emerald-500/20 rounded-xl overflow-hidden"><div class="bg-emerald-50 dark:bg-emerald-500/5 px-4 py-3 border-b border-emerald-200 dark:border-emerald-500/20"><h3 class="font-bold text-sm text-emerald-800 dark:text-emerald-300 flex items-center gap-2"><span class="material-icons select-none text-base">local_shipping</span> 4. ນະໂຍບາຍການຈັດສົ່ງ (ບັງຄັບ) </h3></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ລະບຸເງື່ອນໄຂການຈັດສົ່ງໃຫ້ຄົບຖ້ວນ:</p><div class="bg-slate-50 dark:bg-slate-950/40 rounded-lg p-3 font-mono text-xs text-slate-700 dark:text-slate-300 leading-relaxed border border-slate-200 dark:border-slate-800/50"> - ສົ່ງຟຣີໃນນະຄອນຫຼວງວຽງຈັນ ເມື່ອຊື້ຄົບ 3 ລາຍການຂຶ້ນໄປ<br> - ນອກເຂດນະຄອນຫຼວງ: ຄ່າສົ່ງ 20,000 ກີບ<br> - ໃຊ້ເວລາຈັດສົ່ງ 1-3 ວັນທຳການ (ນະຄອນຫຼວງ) ຫຼື 3-7 ວັນ (ຕ່າງແຂວງ)<br> - ບໍລິການຈັດສົ່ງດ່ວນ (ພາຍໃນ 24 ຊົ່ວໂມງ) ມີຄ່າເພີ່ມ 15,000 ກີບ </div><p class="text-xs text-emerald-600 dark:text-emerald-500 font-semibold">✅ AI ຈະຕອບ &quot;ສົ່ງຟຣີບໍ່? ຮອດໃສແດ່? ຈັກມື້?&quot; ໄດ້ຖືກຕ້ອງ</p></div></div><div class="border border-emerald-200 dark:border-emerald-500/20 rounded-xl overflow-hidden"><div class="bg-emerald-50 dark:bg-emerald-500/5 px-4 py-3 border-b border-emerald-200 dark:border-emerald-500/20"><h3 class="font-bold text-sm text-emerald-800 dark:text-emerald-300 flex items-center gap-2"><span class="material-icons select-none text-base">payments</span> 5. ນະໂຍບາຍການຊຳລະເງິນ (ບັງຄັບ) </h3></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ລະບຸວິທີການຊຳລະທີ່ຮ້ານຮັບ ແລະ ເລກບັນຊີ:</p><div class="bg-slate-50 dark:bg-slate-950/40 rounded-lg p-3 font-mono text-xs text-slate-700 dark:text-slate-300 leading-relaxed border border-slate-200 dark:border-slate-800/50"> - ໂອນຜ່ານທະນາຄານ: BCEL ເລກບັນຊີ 1234567890 (ຊື່: ສະບາຍດີ ຊົອບ)<br> - ເກັບປາຍທາງຈ່າຍ (COD): ມີບໍລິການສະເພາະໃນເຂດນະຄອນຫຼວງ<br> - ໂອນຜ່ານທະນາຄານກະສິກອນ: ເລກບັນຊີ 9876543210 </div><p class="text-xs text-emerald-600 dark:text-emerald-500 font-semibold">✅ AI ຈະຕອບ &quot;ຈ່າຍເງິນແນວໃດ? ມີ COD ບໍ່?&quot; ໄດ້ຖືກຕ້ອງ</p></div></div><div class="border border-emerald-200 dark:border-emerald-500/20 rounded-xl overflow-hidden"><div class="bg-emerald-50 dark:bg-emerald-500/5 px-4 py-3 border-b border-emerald-200 dark:border-emerald-500/20"><h3 class="font-bold text-sm text-emerald-800 dark:text-emerald-300 flex items-center gap-2"><span class="material-icons select-none text-base">assignment_return</span> 6. ນະໂຍບາຍການຄືນເງິນ (ແນະນຳ) </h3></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ລະບຸເງື່ອນໄຂການຄືນເງິນໃຫ້ຊັດເຈນ:</p><div class="bg-slate-50 dark:bg-slate-950/40 rounded-lg p-3 font-mono text-xs text-slate-700 dark:text-slate-300 leading-relaxed border border-slate-200 dark:border-slate-800/50"> - ສາມາດຄືນເງິນໄດ້ພາຍໃນ 7 ວັນ ຫຼັງໄດ້ຮັບສິນຄ້າ<br> - ສິນຄ້າຕ້ອງຢູ່ໃນສະພາບເດີມ ຍັງບໍ່ໄດ້ເປີດໃຊ້<br> - ລູກຄ້າຮັບຜິດຊອບຄ່າສົ່ງຄືນ </div><p class="text-xs text-emerald-600 dark:text-emerald-500 font-semibold">✅ AI ຈະຕອບ &quot;ຄືນເງິນໄດ້ບໍ່? ຈັກມື້?&quot; ໄດ້ຖືກຕ້ອງ</p></div></div><div class="border border-emerald-200 dark:border-emerald-500/20 rounded-xl overflow-hidden"><div class="bg-emerald-50 dark:bg-emerald-500/5 px-4 py-3 border-b border-emerald-200 dark:border-emerald-500/20"><h3 class="font-bold text-sm text-emerald-800 dark:text-emerald-300 flex items-center gap-2"><span class="material-icons select-none text-base">do_not_disturb_on</span> 7. ສິນຄ້າທີ່ຮ້ານບໍ່ມີຂາຍ (ແນະນຳ) </h3></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ລະບຸສິນຄ້າທີ່ຮ້ານບໍ່ມີ ເພື່ອປ້ອງກັນ AI ຕອບວ່າມີ:</p><div class="bg-slate-50 dark:bg-slate-950/40 rounded-lg p-3 font-mono text-xs text-slate-700 dark:text-slate-300 leading-relaxed border border-slate-200 dark:border-slate-800/50"> - ຮ້ານບໍ່ມີຄຸກກີຊັອກໂກແລັດຂາຍ<br> - ຮ້ານບໍ່ມີນ້ຳດື່ມຫຼາຍຊະນິດ<br> - ຮ້ານບໍ່ຮັບສັ່ງເຄັກຕາມໃບສັ່ງ </div><p class="text-xs text-emerald-600 dark:text-emerald-500 font-semibold">✅ ປ້ອງກັນ AI ຕອບຜິດວ່າ &quot;ມີຄຸກກີຂາຍ&quot; ທັງທີ່ຮ້ານບໍ່ມີ</p></div></div><div class="border border-emerald-200 dark:border-emerald-500/20 rounded-xl overflow-hidden"><div class="bg-emerald-50 dark:bg-emerald-500/5 px-4 py-3 border-b border-emerald-200 dark:border-emerald-500/20"><h3 class="font-bold text-sm text-emerald-800 dark:text-emerald-300 flex items-center gap-2"><span class="material-icons select-none text-base">help_outline</span> 8. ຄຳຖາມທີ່ລູກຄ້າມັກຖາມ (FAQ) (ແນະນຳ) </h3></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ຂຽນ FAQ ແບບຖາມ-ຕອບສັ້ນໆ ສຳລັບຄຳຖາມທີ່ພົບເລື້ອຍ:</p><div class="bg-slate-50 dark:bg-slate-950/40 rounded-lg p-3 font-mono text-xs text-slate-700 dark:text-slate-300 leading-relaxed border border-slate-200 dark:border-slate-800/50"> - ຖາມ: ມີສ່ວນຫຼຸດບໍ່?<br>   ຕອບ: ປັດຈຸບັນຮ້ານຍັງບໍ່ມີໂປຣໂມຊັນພິເສດ, ແຕ່ມີສົ່ງຟຣີເມື່ອຊື້ຄົບ 3 ລາຍການ.<br> - ຖາມ: ສິນຄ້າໝົດອາຍຸດົນປານໃດ?<br>   ຕອບ: ແຢມສະຕໍເບີຣີ ໝົດອາຍຸ 6 ເດືອນ, ນ້ຳເຜິ້ງ ໝົດອາຍຸ 2 ປີ.<br> - ຖາມ: ສັ່ງແລ້ວຍົກເລີກໄດ້ບໍ່?<br>   ຕອບ: ສາມາດຍົກເລີກໄດ້ກ່ອນທີ່ຮ້ານຈະຈັດສົ່ງ (ພາຍໃນ 2 ຊົ່ວໂມງຫຼັງສັ່ງ). </div><p class="text-xs text-emerald-600 dark:text-emerald-500 font-semibold">✅ AI ຈະຕອບຄຳຖາມທີ່ພົບເລື້ອຍໆໄດ້ທັນທີ ໂດຍບໍ່ຕ້ອງໃຫ້ພະນັກງານຕອບ</p></div></div><div class="border-2 border-emerald-400 dark:border-emerald-400/40 rounded-xl overflow-hidden bg-emerald-50/80 dark:bg-emerald-500/5"><div class="bg-emerald-500 text-white px-4 py-3 flex items-center gap-2"><span class="material-icons select-none text-base">checklist</span><h3 class="font-bold text-sm">ຕົວຢ່າງເຕັມ: KB ທີ່ດີ (ຄວນໃສ່)</h3><span class="ml-auto text-xs bg-white/20 px-2 py-0.5 rounded-full font-mono">ຄັດລອກໄປໃສ່ກ່ອງ KB ໄດ້ເລີຍ</span></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ນີ້ແມ່ນຕົວຢ່າງ KB ທີ່ສົມບູນ ລວມທຸກປະເພດຂໍ້ມູນທີ່ຄວນໃສ່, ໃຊ້ຮູບແບບ <code>=== ຫົວຂໍ້ ===</code> ຄືກັນກັບທີ່ AI ອ່ານ:</p><div class="bg-white dark:bg-slate-950/80 rounded-lg p-4 font-mono text-xs text-slate-700 dark:text-slate-300 leading-relaxed border border-emerald-300 dark:border-emerald-500/30 whitespace-pre-wrap select-all"> === ຂໍ້ມູນຮ້ານຄ້າ === ຊື່ຮ້ານ: ສະບາຍດີຊົອບ ທີ່ຢູ່: ບ້ານສີຫອມ, ເມືອງຈັນທະບູລີ, ນະຄອນຫຼວງວຽງຈັນ ເບີໂທຕິດຕໍ່: 020 12345678 ເວັບໄຊ: www.sabaideeshop.la ອີເມວ: info@sabaideeshop.la === ເວລາເປີດ-ປິດ === ວັນຈັນ ຫາ ວັນສຸກ: 8:00 - 17:00 ໂມງ ວັນເສົາ: 9:00 - 12:00 ໂມງ ວັນອາທິດ ແລະ ວັນພັກລັດຖະການ: ປິດ === ສິນຄ້າ ແລະ ລາຄາ === 1. ແຢມສະຕໍເບີຣີປອດສານພິດ (250g) — 45,000 ກີບ/ກະປຸກ 2. ເຂົ້າຈີ່ຝຣັ່ງເສັ້ນໃຫຍ່ (200g) — 20,000 ກີບ/ອັນ 3. ນ້ຳເຜິ້ງດອກໄມ້ປ່າ 100% (500ml) — 80,000 ກີບ/ຂວດ 4. ຊາໃບໝາກນາວຫອມ (50g) — 25,000 ກີບ/ຖົງ === ນະໂຍບາຍການຈັດສົ່ງ === - ສົ່ງຟຣີໃນນະຄອນຫຼວງວຽງຈັນ ເມື່ອຊື້ຄົບ 3 ລາຍການຂຶ້ນໄປ - ນອກເຂດນະຄອນຫຼວງ: ຄ່າສົ່ງ 20,000 ກີບ - ໃຊ້ເວລາຈັດສົ່ງ 1-3 ວັນທຳການ (ນະຄອນຫຼວງ) ຫຼື 3-7 ວັນ (ຕ່າງແຂວງ) - ບໍລິການຈັດສົ່ງດ່ວນ (ພາຍໃນ 24 ຊົ່ວໂມງ) ມີຄ່າເພີ່ມ 15,000 ກີບ === ນະໂຍບາຍການຊຳລະເງິນ === - ໂອນຜ່ານທະນາຄານ: BCEL ເລກບັນຊີ 1234567890 (ຊື່: ສະບາຍດີ ຊົອບ) - ເກັບປາຍທາງຈ່າຍ (COD): ມີບໍລິການສະເພາະໃນເຂດນະຄອນຫຼວງ - ໂອນຜ່ານທະນາຄານກະສິກອນ: ເລກບັນຊີ 9876543210 === ນະໂຍບາຍການຄືນເງິນ === - ສາມາດຄືນເງິນໄດ້ພາຍໃນ 7 ວັນ ຫຼັງໄດ້ຮັບສິນຄ້າ - ສິນຄ້າຕ້ອງຢູ່ໃນສະພາບເດີມ ຍັງບໍ່ໄດ້ເປີດໃຊ້ - ລູກຄ້າຮັບຜິດຊອບຄ່າສົ່ງຄືນ === ສິນຄ້າທີ່ຮ້ານບໍ່ມີຂາຍ === - ຮ້ານບໍ່ມີຄຸກກີຊັອກໂກແລັດຂາຍ - ຮ້ານບໍ່ມີນ້ຳດື່ມຫຼາຍຊະນິດ - ຮ້ານບໍ່ຮັບສັ່ງເຄັກຕາມໃບສັ່ງ - ຮ້ານບໍ່ມີກາເຟຮ້ອນຂາຍ === FAQ ທີ່ພົບເລື້ອຍ === ຖາມ: ມີສ່ວນຫຼຸດບໍ່? ຕອບ: ປັດຈຸບັນຮ້ານຍັງບໍ່ມີໂປຣໂມຊັນພິເສດ, ແຕ່ມີສົ່ງຟຣີເມື່ອຊື້ຄົບ 3 ລາຍການ. ຖາມ: ສິນຄ້າໝົດອາຍຸດົນປານໃດ? ຕອບ: ແຢມສະຕໍເບີຣີ ໝົດອາຍຸ 6 ເດືອນ, ນ້ຳເຜິ້ງ ໝົດອາຍຸ 2 ປີ. ຖາມ: ສັ່ງແລ້ວຍົກເລີກໄດ້ບໍ່? ຕອບ: ສາມາດຍົກເລີກໄດ້ກ່ອນທີ່ຮ້ານຈະຈັດສົ່ງ (ພາຍໃນ 2 ຊົ່ວໂມງຫຼັງສັ່ງ). </div><div class="flex items-start gap-2 text-xs text-emerald-700 dark:text-emerald-400 bg-emerald-100/50 dark:bg-emerald-500/10 rounded-lg p-3"><span class="material-icons select-none text-base shrink-0">lightbulb</span><span>✅ KB ນີ້ມີຄຸນສົມບັດຄົບ: ຂໍ້ມູນຊັດເຈນ, ມີຕົວເລກແນ່ນອນ, ບໍ່ມີຄວາມຄິດເຫັນ, ໃຊ້ <code>=== ຫົວຂໍ້ ===</code> ແຍກປະເພດຢ່າງຊັດເຈນ. AI ຈະສາມາດຕອບຄຳຖາມລູກຄ້າໄດ້ຢ່າງຖືກຕ້ອງ 100%.</span></div></div></div></div></div><div class="bg-white dark:bg-slate-900/40 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm dark:shadow-lg transition-colors"><div class="flex items-center gap-3 mb-5"><div class="w-10 h-10 rounded-xl bg-rose-100 dark:bg-rose-500/15 flex items-center justify-center"><span class="material-icons select-none text-xl text-rose-600 dark:text-rose-400">do_not_disturb_alt</span></div><div><h2 class="font-bold text-lg text-slate-900 dark:text-slate-100">ຂໍ້ມູນທີ່ບໍ່ຄວນໃສ່ ❌</h2><p class="text-xs text-slate-500 dark:text-slate-400">ຂໍ້ມູນທີ່ອາດເຮັດໃຫ້ AI ຕອບຜິດ ຫຼື ສ້າງບັນຫາໃຫ້ຮ້ານຄ້າ</p></div></div><div class="grid grid-cols-1 md:grid-cols-2 gap-4"><div class="border border-rose-200 dark:border-rose-500/20 rounded-xl p-4 bg-rose-50/50 dark:bg-rose-500/5 space-y-2"><div class="flex items-center gap-2"><span class="w-6 h-6 rounded-full bg-rose-200 dark:bg-rose-500/20 flex items-center justify-center text-xs font-bold text-rose-700 dark:text-rose-400 shrink-0">1</span><h3 class="font-bold text-sm text-rose-800 dark:text-rose-300">ຄວາມຄິດເຫັນສ່ວນຕົວ ຫຼື ຄວາມຮູ້ສຶກ</h3></div><p class="text-xs text-slate-600 dark:text-slate-400">AI ບໍ່ຄວນຕອບດ້ວຍຄວາມຄິດເຫັນ ຫຼື ຄວາມຮູ້ສຶກສ່ວນຕົວ.</p><div class="bg-white dark:bg-slate-950/60 rounded-lg p-2.5 text-xs font-mono text-rose-500 border border-rose-200 dark:border-rose-500/20 leading-relaxed"> ❌ ແຢມອັນນີ້ແຊບທີ່ສຸດ ຂ້ອຍມັກຫຼາຍ<br> ❌ ຮ້ານເຮົາດີກວ່າຮ້ານອື່ນແນ່ນອນ </div></div><div class="border border-rose-200 dark:border-rose-500/20 rounded-xl p-4 bg-rose-50/50 dark:bg-rose-500/5 space-y-2"><div class="flex items-center gap-2"><span class="w-6 h-6 rounded-full bg-rose-200 dark:bg-rose-500/20 flex items-center justify-center text-xs font-bold text-rose-700 dark:text-rose-400 shrink-0">2</span><h3 class="font-bold text-sm text-rose-800 dark:text-rose-300">ຂໍ້ມູນຄາດເດົາ ຫຼື ບໍ່ແນ່ນອນ</h3></div><p class="text-xs text-slate-600 dark:text-slate-400">AI ຈະເອົາຂໍ້ມູນນີ້ໄປຕອບວ່າເປັນຄວາມຈິງ ເຖິງວ່າມັນຈະບໍ່ແນ່ນອນ.</p><div class="bg-white dark:bg-slate-950/60 rounded-lg p-2.5 text-xs font-mono text-rose-500 border border-rose-200 dark:border-rose-500/20 leading-relaxed"> ❌ ອາດຈະມີສ່ວນຫຼຸດອາທິດໜ້າ ແຕ່ຍັງບໍ່ແນ່ໃຈ<br> ❌ ຄິດວ່າສິນຄ້າຈະມາຮອດມື້ອື່ນ </div></div><div class="border border-rose-200 dark:border-rose-500/20 rounded-xl p-4 bg-rose-50/50 dark:bg-rose-500/5 space-y-2"><div class="flex items-center gap-2"><span class="w-6 h-6 rounded-full bg-rose-200 dark:bg-rose-500/20 flex items-center justify-center text-xs font-bold text-rose-700 dark:text-rose-400 shrink-0">3</span><h3 class="font-bold text-sm text-rose-800 dark:text-rose-300">ຂໍ້ມູນສ່ວນຕົວຂອງລູກຄ້າ</h3></div><p class="text-xs text-slate-600 dark:text-slate-400">ຂໍ້ມູນລູກຄ້າໃຫ້ໃສ່ໃນ CRM, ບໍ່ແມ່ນ KB. KB ເປັນຂໍ້ມູນທີ່ AI ໃຊ້ຮ່ວມກັນທຸກຄົນ.</p><div class="bg-white dark:bg-slate-950/60 rounded-lg p-2.5 text-xs font-mono text-rose-500 border border-rose-200 dark:border-rose-500/20 leading-relaxed"> ❌ ລູກຄ້າຊື່ A ເປັນຄົນຂີ້ຖີ່ມ ມັກຕໍ່ລອງລາຄາ<br> ❌ ເບີໂທລູກຄ້າ: 020 98765432 </div></div><div class="border border-rose-200 dark:border-rose-500/20 rounded-xl p-4 bg-rose-50/50 dark:bg-rose-500/5 space-y-2"><div class="flex items-center gap-2"><span class="w-6 h-6 rounded-full bg-rose-200 dark:bg-rose-500/20 flex items-center justify-center text-xs font-bold text-rose-700 dark:text-rose-400 shrink-0">4</span><h3 class="font-bold text-sm text-rose-800 dark:text-rose-300">ຂໍ້ມູນທີ່ຂັດແຍ່ງກັນ</h3></div><p class="text-xs text-slate-600 dark:text-slate-400">ຂໍ້ມູນທີ່ຂັດແຍ່ງກັນເຮັດໃຫ້ AI ສັບສົນ ແລະ ຕອບຜິດ.</p><div class="bg-white dark:bg-slate-950/60 rounded-lg p-2.5 text-xs font-mono text-rose-500 border border-rose-200 dark:border-rose-500/20 leading-relaxed"> ❌ ສົ່ງຟຣີທຸກຄຳສັ່ງ<br> (ແຕ່ຂ້າງລຸ່ມ: ສົ່ງຟຣີເມື່ອຊື້ຄົບ 3 ລາຍການ) </div></div><div class="border border-rose-200 dark:border-rose-500/20 rounded-xl p-4 bg-rose-50/50 dark:bg-rose-500/5 space-y-2"><div class="flex items-center gap-2"><span class="w-6 h-6 rounded-full bg-rose-200 dark:bg-rose-500/20 flex items-center justify-center text-xs font-bold text-rose-700 dark:text-rose-400 shrink-0">5</span><h3 class="font-bold text-sm text-rose-800 dark:text-rose-300">ຂໍ້ມູນທີ່ປ່ຽນແປງເລື້ອຍໆ</h3></div><p class="text-xs text-slate-600 dark:text-slate-400">ຂໍ້ມູນທີ່ປ່ຽນແປງປະຈຳວັນ ຫຼື ປະຈຳອາທິດ ຄວນຫຼີກລ່ຽງ ເພາະທ່ານອາດລືມອັບເດດ KB.</p><div class="bg-white dark:bg-slate-950/60 rounded-lg p-2.5 text-xs font-mono text-rose-500 border border-rose-200 dark:border-rose-500/20 leading-relaxed"> ❌ ມື້ນີ້ສ່ວນຫຼຸດ 20% ສະເພາະມື້ນີ້ເທົ່ານັ້ນ<br> ❌ ອາທິດນີ້ມີສິນຄ້າໃໝ່ເຂົ້າ 3 ລາຍການ </div></div><div class="border border-rose-200 dark:border-rose-500/20 rounded-xl p-4 bg-rose-50/50 dark:bg-rose-500/5 space-y-2"><div class="flex items-center gap-2"><span class="w-6 h-6 rounded-full bg-rose-200 dark:bg-rose-500/20 flex items-center justify-center text-xs font-bold text-rose-700 dark:text-rose-400 shrink-0">6</span><h3 class="font-bold text-sm text-rose-800 dark:text-rose-300">ການປຽບທຽບຄູ່ແຂ່ງ</h3></div><p class="text-xs text-slate-600 dark:text-slate-400">AI ບໍ່ຄວນວິຈານ ຫຼື ປຽບທຽບຮ້ານອື່ນ ເພາະອາດມີປັນຫາດ້ານກົດໝາຍ.</p><div class="bg-white dark:bg-slate-950/60 rounded-lg p-2.5 text-xs font-mono text-rose-500 border border-rose-200 dark:border-rose-500/20 leading-relaxed"> ❌ ຮ້ານອື່ນຂາຍແພງກວ່າ ແລະ ຄຸນນະພາບບໍ່ດີ<br> ❌ ຮ້ານ A ສົ່ງຊ້າ ແຕ່ຮ້ານເຮົາສົ່ງໄວ </div></div></div><div class="border-2 border-rose-400 dark:border-rose-400/40 rounded-xl overflow-hidden bg-rose-50/80 dark:bg-rose-500/5 mt-5"><div class="bg-rose-500 text-white px-4 py-3 flex items-center gap-2"><span class="material-icons select-none text-base">do_not_disturb_alt</span><h3 class="font-bold text-sm">ຕົວຢ່າງເຕັມ: KB ທີ່ບໍ່ດີ (ບໍ່ຄວນໃສ່)</h3><span class="ml-auto text-xs bg-white/20 px-2 py-0.5 rounded-full font-mono">KB ແບບນີ້ຈະເຮັດໃຫ້ AI ຕອບຜິດ</span></div><div class="p-4 space-y-2 text-sm"><p class="text-slate-600 dark:text-slate-400">ນີ້ແມ່ນຕົວຢ່າງ KB ທີ່ບໍ່ດີ ທີ່ລວມຂໍ້ມູນທີ່ບໍ່ຄວນໃສ່ໄວ້ນຳກັນ — ສັງເກດບັນຫາທີ່ເກີດຂຶ້ນ:</p><div class="bg-white dark:bg-slate-950/80 rounded-lg p-4 font-mono text-xs text-rose-600 dark:text-rose-400 leading-relaxed border border-rose-300 dark:border-rose-500/30 whitespace-pre-wrap select-all"> === ຂໍ້ມູນຮ້ານຄ້າ === ຊື່ຮ້ານ: ສະບາຍດີຊົອບ - ຮ້ານທີ່ດີທີ່ສຸດໃນເມືອງ! ❤️ ທີ່ຢູ່: ບ້ານສີຫອມ... ປະມານໃກ້ໆໂຮງຮຽນ ເຂົ້າມາງ່າຍໆ === ເວລາເປີດ-ປິດ === ວັນຈັນ ຫາ ວັນສຸກ: 8:00 - 17:00 ໂມງ (ອາດຈະປິດຊ້າກວ່າບາງມື້) ວັນເສົາ: ປົກກະຕິແລ້ວເປີດ 9:00 - 12:00 ໂມງ ວັນອາທິດ: ຄິດວ່າປິດ ແຕ່ບໍ່ແນ່ໃຈ === ສິນຄ້າ ແລະ ລາຄາ === 1. ແຢມສະຕໍເບີຣີ - ແຊບທີ່ສຸດ! ຂ້ອຍມັກກິນຫຼາຍ (250g) — ປະມານ 45,000 ກີບ 2. ເຂົ້າຈີ່ຝຣັ່ງ - ດີກວ່າຮ້ານຂ້າງທາງແນ່ນອນ (200g) — 20,000 ກີບ/ອັນ 3. ມື້ນີ້ສ່ວນຫຼຸດ 20% ສະເພາະມື້ນີ້ເທົ່ານັ້ນ! === ນະໂຍບາຍການຈັດສົ່ງ === - ສົ່ງຟຣີທຸກຄຳສັ່ງ (ຍົກເວັ້ນບາງກໍລະນີ) - ນອກເຂດ: ຄ່າສົ່ງປະມານ 20,000 ກີບ - ໃຊ້ເວລາຈັດສົ່ງ 1-3 ວັນທຳການ... ຄິດວ່ານ່າ === ນະໂຍບາຍການຄືນເງິນ === - ຄືນເງິນໄດ້ ຖ້າລູກຄ້າບໍ່ພໍໃຈ (ແຕ່ບໍ່ຄືນໃຫ້ລູກຄ້າຄົນນັ້ນ ເພາະຂີ້ຖີ່ມ) - ສິນຄ້າຕ້ອງຢູ່ໃນສະພາບເດີມ === ສິນຄ້າທີ່ຮ້ານບໍ່ມີຂາຍ === - ຮ້ານບໍ່ມີຄຸກກີຊັອກໂກແລັດ... ແຕ່ເຮົາມີເຄັກຊັອກໂກແລັດ ແຊບກວ່າ === ລູກຄ້າພິເສດ === ລູກຄ້າ A (ເບີໂທ: 020 12345678) - ລູກຄ້າປະຈຳ ມັກສັ່ງແຢມສະຕໍເບີຣີ </div><div class="flex items-start gap-2 text-xs text-rose-700 dark:text-rose-400 bg-rose-100/50 dark:bg-rose-500/10 rounded-lg p-3"><span class="material-icons select-none text-base shrink-0">warning</span><span>⚠️ KB ນີ້ມີບັນຫາຫຼາຍຢ່າງ: ① ຄວາມຄິດເຫັນ ແລະ ອາລົມ (&quot;ດີທີ່ສຸດ&quot;, &quot;ແຊບ&quot;, ❤️) ② ຂໍ້ມູນຄາດເດົາ (&quot;ອາດຈະ&quot;, &quot;ຄິດວ່າ&quot;, &quot;ປະມານ&quot;) ③ ຂໍ້ມູນຊົ່ວຄາວ (&quot;ມື້ນີ້ສ່ວນຫຼຸດ 20%&quot;) ④ ປຽບທຽບຄູ່ແຂ່ງ (&quot;ດີກວ່າຮ້ານຂ້າງທາງ&quot;) ⑤ ຂໍ້ມູນຂັດແຍ່ງ (&quot;ສົ່ງຟຣີທຸກຄຳສັ່ງ&quot; ແຕ່ &quot;ຍົກເວັ້ນ...&quot;) ⑥ ຂໍ້ມູນສ່ວນຕົວລູກຄ້າ (ຊື່ ແລະ ເບີໂທ).</span></div></div></div></div><div class="bg-indigo-50 dark:bg-indigo-500/5 border border-indigo-200 dark:border-indigo-500/20 rounded-2xl p-6 shadow-sm dark:shadow-lg transition-colors"><div class="flex items-center gap-3 mb-4"><div class="w-10 h-10 rounded-xl bg-indigo-100 dark:bg-indigo-500/15 flex items-center justify-center"><span class="material-icons select-none text-xl text-indigo-600 dark:text-indigo-400">auto_awesome</span></div><h2 class="font-bold text-lg text-slate-900 dark:text-slate-100">ຫຼັກການສຳຄັນ ແລະ ເຄັດລັບ</h2></div><div class="grid grid-cols-1 md:grid-cols-3 gap-4"><div class="bg-white dark:bg-slate-900/60 rounded-xl p-4 border border-indigo-200 dark:border-indigo-500/20 space-y-2"><div class="flex items-center gap-2"><span class="material-icons select-none text-lg text-indigo-600 dark:text-indigo-400">checklist</span><h3 class="font-bold text-sm text-slate-800 dark:text-slate-200">ຊັດເຈນ ແລະ ຖືກຕ້ອງ</h3></div><p class="text-xs text-slate-500 dark:text-slate-400 leading-relaxed"> ໃຊ້ພາສາທີ່ຊັດເຈນ, ບໍ່ກຳກົມ, ມີຕົວເລກທີ່ແນ່ນອນ. ກວດສອບຄວາມຖືກຕ້ອງກ່ອນບັນທຶກທຸກຄັ້ງ. </p></div><div class="bg-white dark:bg-slate-900/60 rounded-xl p-4 border border-indigo-200 dark:border-indigo-500/20 space-y-2"><div class="flex items-center gap-2"><span class="material-icons select-none text-lg text-indigo-600 dark:text-indigo-400">update</span><h3 class="font-bold text-sm text-slate-800 dark:text-slate-200">ປັບປຸງຢູ່ສະເໝີ</h3></div><p class="text-xs text-slate-500 dark:text-slate-400 leading-relaxed"> ເມື່ອລາຄາປ່ຽນ, ເວລາເປີດ-ປິດປ່ຽນ, ຫຼື ມີນະໂຍບາຍໃໝ່ — ໃຫ້ອັບເດດ KB ທັນທີ. AI ຈະຕອບຕາມຂໍ້ມູນຫຼ້າສຸດເທົ່ານັ້ນ. </p></div><div class="bg-white dark:bg-slate-900/60 rounded-xl p-4 border border-indigo-200 dark:border-indigo-500/20 space-y-2"><div class="flex items-center gap-2"><span class="material-icons select-none text-lg text-indigo-600 dark:text-indigo-400">science</span><h3 class="font-bold text-sm text-slate-800 dark:text-slate-200">ທົດສອບສະເໝີ</h3></div><p class="text-xs text-slate-500 dark:text-slate-400 leading-relaxed"> ຫຼັງແກ້ໄຂ KB ແລ້ວ, ໃຊ້ <strong>Simulator</strong> (ເຄື່ອງທົດລອງ) ຢູ່ໜ້າຕັ້ງຄ່າເພຈ໌ ເພື່ອທົດສອບວ່າ AI ຕອບຖືກຕ້ອງຕາມທີ່ຄາດໄວ້. </p></div></div></div><div class="bg-white dark:bg-slate-900/40 border border-slate-200 dark:border-slate-800 rounded-2xl p-6 shadow-sm dark:shadow-lg transition-colors"><h2 class="font-bold text-lg text-slate-900 dark:text-slate-200 flex items-center gap-2 mb-4"><span class="material-icons select-none text-indigo-600 dark:text-indigo-400">table_chart</span> ຕາຕະລາງສະຫຼຸບ ຄວນ / ບໍ່ຄວນ </h2><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b border-slate-200 dark:border-slate-800"><th class="text-left py-3 px-4 font-bold text-slate-700 dark:text-slate-300">ປະເພດຂໍ້ມູນ</th><th class="text-left py-3 px-4 font-bold text-emerald-700 dark:text-emerald-400">ຄວນໃສ່?</th><th class="text-left py-3 px-4 font-bold text-slate-700 dark:text-slate-300">ເຫດຜົນ</th></tr></thead><tbody class="divide-y divide-slate-200 dark:divide-slate-800/80"><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">ຂໍ້ມູນຮ້ານຄ້າ (ຊື່, ທີ່ຢູ່, ເບີໂທ)</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold"><span class="material-icons select-none text-sm">check_circle</span> ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">ລູກຄ້າຕ້ອງການຂໍ້ມູນຕິດຕໍ່ ແລະ ທີ່ຕັ້ງ</td></tr><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">ເວລາເປີດ-ປິດທີ່ແນ່ນອນ</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold"><span class="material-icons select-none text-sm">check_circle</span> ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">ຄຳຖາມຍອດຮິດ ທີ່ລູກຄ້າຖາມຫຼາຍທີ່ສຸດ</td></tr><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">ສິນຄ້າ ແລະ ລາຄາ</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold"><span class="material-icons select-none text-sm">check_circle</span> ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">ລູກຄ້າຢາກຮູ້ວ່າມີຫຍັງຂາຍ ແລະ ລາຄາເທົ່າໃດ</td></tr><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">ນະໂຍບາຍ (ສົ່ງ, ຊຳລະ, ຄືນເງິນ)</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold"><span class="material-icons select-none text-sm">check_circle</span> ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">ປ້ອງກັນການເຂົ້າໃຈຜິດ ແລະ ຂໍ້ຂັດແຍ່ງ</td></tr><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">FAQ (ຖາມ-ຕອບ)</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold"><span class="material-icons select-none text-sm">check_circle</span> ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">ປະຫຍັດເວລາພະນັກງານ ຕອບຄຳຖາມຊ້ຳໆ</td></tr><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">ສິນຄ້າທີ່ບໍ່ມີຂາຍ</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-emerald-600 dark:text-emerald-400 font-bold"><span class="material-icons select-none text-sm">check_circle</span> ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">ປ້ອງກັນ AI ຕອບວ່າມີທັງທີ່ບໍ່ມີ</td></tr><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20 bg-rose-50/30 dark:bg-rose-500/5"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">ຄວາມຄິດເຫັນ / ຄວາມຮູ້ສຶກ</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-rose-600 dark:text-rose-400 font-bold"><span class="material-icons select-none text-sm">do_not_disturb_alt</span> ບໍ່ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">AI ຕ້ອງເປັນກາງ ແລະ ມືອາຊີບ</td></tr><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20 bg-rose-50/30 dark:bg-rose-500/5"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">ຂໍ້ມູນຄາດເດົາ</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-rose-600 dark:text-rose-400 font-bold"><span class="material-icons select-none text-sm">do_not_disturb_alt</span> ບໍ່ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">AI ຈະຄິດວ່າມັນເປັນຄວາມຈິງ ແລະ ຕອບໄປ</td></tr><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20 bg-rose-50/30 dark:bg-rose-500/5"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">ຂໍ້ມູນສ່ວນຕົວລູກຄ້າ</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-rose-600 dark:text-rose-400 font-bold"><span class="material-icons select-none text-sm">do_not_disturb_alt</span> ບໍ່ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">ໃຊ້ CRM ສຳລັບຂໍ້ມູນສ່ວນຕົວລູກຄ້າ</td></tr><tr class="hover:bg-slate-50 dark:hover:bg-slate-950/20 bg-rose-50/30 dark:bg-rose-500/5"><td class="py-3 px-4 font-semibold text-slate-800 dark:text-slate-200">ປຽບທຽບຄູ່ແຂ່ງ</td><td class="py-3 px-4"><span class="inline-flex items-center gap-1 text-rose-600 dark:text-rose-400 font-bold"><span class="material-icons select-none text-sm">do_not_disturb_alt</span> ບໍ່ຄວນ</span></td><td class="py-3 px-4 text-slate-500 dark:text-slate-400">ອາດມີປັນຫາດ້ານກົດໝາຍ ແລະ ຈັນຍາບັນ</td></tr></tbody></table></div></div>',6)),t("div",p,[a(s,{to:"/dashboard/pages",class:"inline-flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white font-bold text-sm rounded-xl transition-all shadow-md shadow-indigo-600/20"},{default:r(()=>[...e[1]||(e[1]=[t("span",{class:"material-icons select-none text-base"},"arrow_back",-1),d(" ກັບຄືນຫາໜ້າເພຈ໌ ",-1)])]),_:1})])])}}});export{f as default};
